Definition ST_FR : Z := 368.
Definition ST_ENTRY : Z := 0x740bc.
Definition ST_RET : Z := 0x7416c.     (* [comment removed for export] *)
Definition ST_ONE : Z := 0x12b30.     (* [comment removed for export] *)

