Definition stm_run := sym_exec RSEGS 400 true [ST_RET] (SCR [] [] []) (SS ST_ENTRY stm_sr [] stm_kn 36) [].
Definition stm_res := Eval vm_compute in stm_run.
Definition stm_car := Eval vm_compute in (carry (s_log (fst (fst stm_res))) stm_kn []).

Lemma stm_res_pc : s_pc (fst (fst stm_res)) = ST_RET. Proof. vm_compute. reflexivity. Qed.
Lemma stm_res_scs : snd (fst stm_res) = []. Proof. vm_compute. reflexivity. Qed.
Lemma stm_car_scs : snd (fst stm_car) = [] /\ snd stm_car = []. Proof. vm_compute. split; reflexivity. Qed.
Lemma stm_covered : log_covered (st_regions 3) (s_log (fst (fst stm_res))) = true. Proof. vm_compute. reflexivity. Qed.
Lemma stm_same : same_regs stm_sr (s_regs (fst (fst stm_res))) callee_saved = true. Proof. vm_compute. reflexivity. Qed.
Lemma stm_a0 : nth 10 (s_regs (fst (fst stm_res))) (ELit 0) = ELit 18446744073709551615. Proof. vm_compute. reflexivity. Qed.
Lemma stm_end : kread RSEGS (fst (fst stm_car)) (EVar 3) 0 8 = Some (EAlu ALU_ADD (EVar 1) (ELit 2)). Proof. vm_compute. reflexivity. Qed.

Section PackageM.
  Variable rsh : bvmap 5 word -> Prop.
  Hypothesis rsh_upd : forall (R : bvmap 5 word) (rd : reg) (v : word), bv_eqb rd 0 = false -> rsh R -> rsh (regupd R rd v).
  Variables (regs : bvmap 5 word) (mem rom : word -> option byte) (sp s endp : word) (can : Z).
  Hypothesis SH : stmH mem sp s endp can.
  Hypothesis RSH : rsh regs.
  Hypothesis R2 : getr regs 2 = sp.
  Hypothesis R10 : getr regs 10 = s.
  Hypothesis R11 : getr regs 11 = endp.
  Hypothesis R12 : getr regs 12 = Z_to_bv 64 0.
  Let E := stmE regs sp s endp can.

  Definition stm_post (regs' : bvmap 5 word) (mem' : word -> option byte) : Prop :=
      msteps RSEGS (mkst regs (Z_to_bv 64 ST_ENTRY) mem rom) (mkst regs' (Z_to_bv 64 ST_RET) mem' rom)
      /\ keeps_cs regs regs'
      /\ getr regs' 10 = Z_to_bv 64 18446744073709551615
      /\ frame_mod mem mem' [(Z_to_bv 64 (bv_unsigned sp - 368), 368); (Z_to_bv 64 (bv_unsigned endp), 8)]
      /\ rdn RSEGS mem' (Z_to_bv 64 (bv_unsigned endp)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (bv_unsigned s + 2)))
      /\ rsh regs'.
Scheme kc__3 := Elimination for Corelib.Init.Logic.ex Sort Prop.
Scheme kc__4 := Elimination for Corelib.Init.Logic.and Sort Prop.
Scheme kc__5 := Elimination for Corelib.Init.Logic.or Sort Prop.
Scheme kc__6 := Elimination for Corelib.Init.Logic.False Sort Prop.

  Lemma stm_pack : forall ss' scr' kn' hs',
    sym_exec RSEGS 400 true [ST_RET] (SCR [] [] []) (SS ST_ENTRY stm_sr [] stm_kn 36) [] = (ss', [], scr') ->
    s_pc ss' = ST_RET ->
    log_covered (st_regions 3) (s_log ss') = true ->
    same_regs stm_sr (s_regs ss') callee_saved = true ->
    nth 10 (s_regs ss') (ELit 0) = ELit 18446744073709551615 ->
    carry (s_log ss') stm_kn [] = (kn', [], hs') ->
    kread RSEGS kn' (EVar 3) 0 8 = Some (EAlu ALU_ADD (EVar 1) (ELit 2)) ->
    exists regs' mem', stm_post regs' mem'.
