Definition stp_run := sym_exec RSEGS 400 true [ST_RET] (SCR [] [] []) (SS ST_ENTRY stp_sr [] stp_kn 35) [].
Definition stp_res := Eval vm_compute in stp_run.
Definition stp_car := Eval vm_compute in (carry (s_log (fst (fst stp_res))) stp_kn []).

Lemma stp_res_pc : s_pc (fst (fst stp_res)) = ST_RET. Proof. vm_compute. reflexivity. Qed.
Lemma stp_res_scs : snd (fst stp_res) = []. Proof. vm_compute. reflexivity. Qed.
Lemma stp_car_scs : snd (fst stp_car) = [] /\ snd stp_car = []. Proof. vm_compute. split; reflexivity. Qed.
Lemma stp_covered : log_covered (st_regions 1) (s_log (fst (fst stp_res))) = true. Proof. vm_compute. reflexivity. Qed.
Lemma stp_same : same_regs stp_sr (s_regs (fst (fst stp_res))) callee_saved = true. Proof. vm_compute. reflexivity. Qed.
Lemma stp_a0 : nth 10 (s_regs (fst (fst stp_res))) (ELit 0) = ELit 1. Proof. vm_compute. reflexivity. Qed.
Lemma stp_end : kread RSEGS (fst (fst stp_car)) (EVar 1) 0 8 = Some (ELit 76593). Proof. vm_compute. reflexivity. Qed.

Section PackageP.
  Variable rsh : bvmap 5 word -> Prop.
  Hypothesis rsh_upd : forall (R : bvmap 5 word) (rd : reg) (v : word), bv_eqb rd 0 = false -> rsh R -> rsh (regupd R rd v).
  Variables (regs : bvmap 5 word) (mem rom : word -> option byte) (sp endp : word) (can : Z).
  Hypothesis SH : stpH mem sp endp can.
  Hypothesis RSH : rsh regs.
  Hypothesis R2 : getr regs 2 = sp.
  Hypothesis R10 : getr regs 10 = Z_to_bv 64 ST_ONE.
  Hypothesis R11 : getr regs 11 = endp.
  Hypothesis R12 : getr regs 12 = Z_to_bv 64 0.
  Let E := stpE regs sp endp can.

